function unitCard(type='p'){const t=TYPES[type];$('unitCard').innerHTML=`<div class="unit-hero"><div class="unit-symbol">${SYMBOLS.w[type]}</div><div><h2>${t.name}</h2><small>${t.role}</small></div></div><p class="unit-description">${t.description}</p><div class="stat"><span>SINH LỰC</span><b>${t.hp} HP</b></div><div class="stat-line"><i style="width:${t.hp/190*100}%"></i></div><div class="stat"><span>SÁT THƯƠNG</span><b>${t.damage} / đòn</b></div><div class="stat-line"><i style="width:${t.damage/25*100}%"></i></div><div class="stat"><span>VŨ KHÍ</span><b>${t.weapon}</b></div><div class="special-tag">✦ ${t.skill}</div>`;}
function squareName(i){return'abcdefgh'[i%8]+(8-Math.floor(i/8));}
function render(){const board=$('board');board.innerHTML='';for(let i=0;i<64;i++){const p=state.board[i],r=Math.floor(i/8),c=i%8,m=legal.find(x=>x.to===i),el=document.createElement('button');el.className='square'+((r+c)%2?' black-square':'')+(last.includes(i)?' last':'')+(selected===i?' selected':'')+(m?(Chess.target(state,m)?' legal attack':' legal'):'');el.setAttribute('role','gridcell');el.setAttribute('aria-label',squareName(i)+(p?' '+(p.color==='w'?'Trắng ':'Đen ')+TYPES[p.type].name:' ô trống'));el.setAttribute('aria-selected',selected===i);if(c===0)el.innerHTML+=`<span class="coord rank">${8-r}</span>`;if(r===7)el.innerHTML+=`<span class="coord file">${'abcdefgh'[c]}</span>`;if(p)el.innerHTML+=`<span class="piece ${p.color==='b'?'black':''}">${SYMBOLS[p.color][p.type]}</span>`;el.onclick=()=>clickSquare(i);board.append(el);}
$('p2Name').textContent=mode==='ai'?`Máy · ${level==='easy'?'Dễ':level==='hard'?'Khó':'Thường'}`:'Người chơi 2 · Quân Đen';document.querySelector('.player-bar:nth-of-type(3) strong')?.replaceChildren(document.createTextNode(mode==='ai'?'Bạn · Quân Trắng':'Người chơi 1 · Quân Trắng'));
$('p1Status').textContent=state.winner?'Trận đấu kết thúc':state.turn==='w'?'Đang đi quân':'Đang chờ lượt';$('p2Status').textContent=state.winner?'Trận đấu kết thúc':state.turn==='b'?(mode==='ai'?'Đang suy nghĩ…':'Đang đi quân'):'Đang chờ lượt';$('turnLabel').textContent=state.winner?'TRẬN ĐẤU KẾT THÚC':`LƯỢT QUÂN ${state.turn==='w'?'TRẮNG':'ĐEN'}`;$('moveCount').textContent=`NƯỚC ${String(state.move).padStart(2,'0')}`;$('lostWhite').textContent=lost.w.map(t=>SYMBOLS.w[t]).join('');$('lostBlack').textContent=lost.b.map(t=>SYMBOLS.b[t]).join('');if(history.length){$('history').innerHTML=history.map((h,i)=>`<div class="log-item"><span>${String(i+1).padStart(2,'0')} · ${h.color==='w'?'QUÂN TRẮNG':'QUÂN ĐEN'}</span>${h.text}</div>`).join('');$('history').scrollTop=$('history').scrollHeight;}}
function clickSquare(i){if(battle||state.winner||(mode==='ai'&&state.turn==='b'))return;const m=legal.find(m=>m.to===i);if(m){selected=null;legal=[];makeMove(m);return;}const p=state.board[i];if(p?.color===state.turn){selected=i;legal=Chess.moves(state,i);unitCard(p.type);tone(350,.04,'sine');}else{selected=null;legal=[];}render();}
function makeMove(m){const p=state.board[m.from],t=Chess.target(state,m);if(t){startBattle(m,p,t);return;}finishMove(m,true);tone(190,.06,'triangle');}
function animateBoardMove(m){if(typeof window.matchMedia==='function'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const cells=$('board').children;function slide(from,to){const piece=cells[to]?.querySelector?.('.piece');if(!piece||!piece.animate)return;const a=cells[from].getBoundingClientRect(),b=cells[to].getBoundingClientRect();piece.animate([{transform:`translate(${a.left-b.left}px,${a.top-b.top}px) scale(1.08)`,filter:'drop-shadow(0 10px 5px #12284066)'},{transform:'translate(0,0) scale(1)'}],{duration:340,easing:'cubic-bezier(.2,.75,.25,1)'});}slide(m.from,m.to);if(m.castle)slide(m.castle.from,m.castle.to);}
function finishMove(m,win){const p={...state.board[m.from]},t=Chess.target(state,m),before=p.type,loser=Chess.resolve(state,m,win);if(loser)lost[loser.color].push(loser.type);last=[m.from,m.to];let text=`${TYPES[before].name} ${squareName(m.from)} → ${squareName(m.to)}`;if(t)text+=` · <b>${win?'Tấn công thắng':'Phòng thủ thắng'}</b><br>${TYPES[loser.type].name} ${loser.color==='w'?'Trắng':'Đen'} bị hạ`;else if(state.board[m.to]?.type!==before)text+=' · <b>Phong Hậu</b>';else if(m.castle)text+=' · Nhập thành';history.push({color:p.color,text});render();if(!t||win)animateBoardMove(m);if(state.winner){$('resultTitle').textContent=`Quân ${state.winner==='w'?'Trắng':'Đen'} chiến thắng!`;$('resultText').textContent='Vua đối phương đã bị hạ gục. Chiến trường có chủ nhân mới.';$('resultDialog').showModal();tone(650,.4,'triangle');return;}scheduleAI();}
function scheduleAI(){clearTimeout(aiTimeout);if(mode==='ai'&&state.turn==='b'&&!state.winner&&!battle)aiTimeout=setTimeout(()=>{const m=Chess.chooseAI(state,level);if(m)makeMove(m);else skipBlocked();},650);else if(!state.winner&&!battle&&!Chess.allMoves(state).length)skipBlocked();}
function skipBlocked(){history.push({color:state.turn,text:'Không có nước đi · bỏ lượt'});state.turn=state.turn==='w'?'b':'w';state.enPassant=null;state.move++;render();if(Chess.allMoves(state).length)scheduleAI();else{state.winner='draw';$('resultTitle').textContent='Hòa — bàn cờ bị khóa';$('resultText').textContent='Cả hai bên đều không còn nước đi hợp lệ.';$('resultDialog').showModal();}}
function reset(){clearTimeout(aiTimeout);battle=null;keys.clear();if(typeof tapTimes!=='undefined'){tapTimes.clear();dashRequests.fill(false);}$('battleOverlay').classList.add('hidden');$('resultDialog').close();state=Chess.initial();selected=null;legal=[];history=[];last=[];lost={w:[],b:[]};$('history').innerHTML='<div class="empty-log"><span>⚑</span><p>Chiến trường đang chờ.</p><small>Chọn một quân để bắt đầu.</small></div>';unitCard();render();}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(mode===b.dataset.mode)return;mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-level]').forEach(x=>x.disabled=mode==='local');$('modeNote').textContent=mode==='ai'?'Bạn cầm quân Trắng. Máy cầm quân Đen.':'Hai người chơi trên cùng một bàn phím.';reset();});document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=b.dataset.level;document.querySelectorAll('[data-level]').forEach(x=>x.classList.toggle('active',x===b));render();});$('newBtn').onclick=reset;$('againBtn').onclick=reset;$('helpBtn').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();$('soundBtn').onclick=()=>{sound=!sound;$('soundBtn').textContent=sound?'♪':'♫̸';$('soundBtn').setAttribute('aria-pressed',sound);if(sound)tone(400);};
