function pause(){if(!battle||battle.ended)return;battle.paused=!battle.paused;keys.clear();$('pauseBtn').textContent=battle.paused?'▶ Tiếp tục':'Ⅱ Tạm dừng';if(battle.paused){$('battleMessage').style.display='flex';$('battleMessage').innerHTML='TẠM DỪNG<small>Nhấn Esc hoặc Tiếp tục để trở lại</small>';}else $('battleMessage').style.display=battle.countdown>0?'flex':'none';}
function keyName(e){return /^Numpad[0-3]$/.test(e.code)?e.code.slice(-1):e.key.toLowerCase();}
$('pauseBtn').onclick=pause;window.addEventListener('keydown',e=>{const k=keyName(e);if(battle&&['arrowleft','arrowright','arrowup','arrowdown','a','d','w','s','f','g','q','k','l','p','escape',' '].includes(k)){e.preventDefault();if(k==='escape'&&!e.repeat)pause();else if(!battle.paused){registerTap(k,e.repeat);keys.add(k);}}});window.addEventListener('keyup',e=>keys.delete(keyName(e)));window.addEventListener('blur',()=>{keys.clear();if(battle&&!battle.paused&&!battle.ended)pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&battle&&!battle.paused&&!battle.ended)pause();});document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);registerTap(b.dataset.key);keys.add(b.dataset.key);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key);});
