function aiCombat(f,enemy,dt){f.aiThink-=dt;if(f.aiThink>0)return f.intent;const cfg=level==='easy'?{reaction:.48,attack:.55,block:.15,special:.2}:level==='hard'?{reaction:.12,attack:.94,block:.66,special:.8}:{reaction:.28,attack:.8,block:.37,special:.48};f.aiThink=cfg.reaction;const dist=Math.abs(f.x-enemy.x),ranged=['r','q','b'].includes(f.type),desired=ranged?370:75,approach=dist>desired,retreat=ranged&&dist<210;f.intent={left:(approach&&f.x>enemy.x)||(retreat&&f.x<enemy.x),right:(approach&&f.x<enemy.x)||(retreat&&f.x>enemy.x),attack:dist<f.range&&Math.random()<cfg.attack,special:dist<f.range+90&&Math.random()<cfg.special,block:((enemy.anim>0||battle.projectiles.some(p=>p.owner!==f&&Math.abs(p.x-f.x)<240))&&Math.random()<cfg.block),jump:Math.random()<(ranged?.10:.15)||battle.projectiles.some(p=>p.owner!==f&&Math.abs(p.x-f.x)<180&&Math.random()<cfg.block)};return f.intent;}
