function attack(f,enemy,special){if(f.attackCd>0||(special&&f.specialCd>0)||f.block||f.energy<(special?35:f.heavy?18:3))return;f.energy-=special?35:f.heavy?18:3;f.attackCd=special?f.cooldown*1.4:f.cooldown;if(special)f.specialCd=f.special;f.anim=special?.38:.22;f.specialAnim=special;const ranged=['r','q','b'].includes(f.type);if(ranged){const count=special?(f.type==='r'?1:f.type==='q'?5:3):1;for(let i=0;i<count;i++)battle.projectiles.push({owner:f,x:f.x+f.facing*42-f.facing*i*22,y:f.y-65+(i%3-1)*(special?13:0),vx:f.facing*(f.type==='b'?530:760),vy:f.aimUp?-210:0,damage:f.damage*(f.heavy?1.65:1)*(special?(f.type==='r'?2.7:1.05):1),radius:special&&f.type==='r'?10:f.type==='b'?9:5,life:2});tone(f.type==='b'?500:200,.07,'square');}else{if(special&&f.type==='p')f.x=Math.max(45,Math.min(1155,f.x+f.facing*115));const dist=Math.abs(f.x-enemy.x),range=f.range+(special?(f.type==='n'?110:45):0);if(dist<range&&Math.abs(f.y-enemy.y)<100)hit(f,enemy,f.damage*(special?2:1));if(special&&f.type==='k')f.hp=Math.min(f.maxHp,f.hp+65);tone(280,.08,'triangle');}}
